# 5.5 culture
CH.append(dict(id="e5-schools", theme="culture", el="Στωικοί και Επικούρειοι: πώς να ζεις σε έναν μεγάλο κόσμο", title="Stoics and Epicureans: how to live in a big world", dates="περ. 307–100 π.Χ.",
  image="epicurus",
  summary_en="When the city-state lost its weight, philosophy turned to the individual: Diogenes the 'citizen of the world', Zeno's Stoa, Epicurus' Garden, and the everyday words they left to Greek and to English.",
  sections=[
    S("cosmopolitan", "Ο πολίτης του κόσμου", "The citizen of the world", [
      P("Στην κλασική εποχή ο άνθρωπος οριζόταν κυρίως ως πολίτης μιας πόλης. Στον ελληνιστικό κόσμο των μεγάλων βασιλείων η πόλη είχε χάσει μεγάλο μέρος της σημασίας της. Πολλοί άνθρωποι ζούσαν μακριά από την πατρίδα τους και ένιωθαν ότι η μοίρα τους αποφασιζόταν από βασιλιάδες που δεν είχαν δει ποτέ. Η φιλοσοφία στράφηκε σε ένα νέο ερώτημα: πώς μπορεί ο καθένας να είναι ευτυχισμένος, ό,τι κι αν συμβαίνει γύρω του.",
        "In the classical age a person was defined mainly as the citizen of a polis. In the Hellenistic world of great kingdoms the city had lost much of its importance. Many people lived far from home and felt that their fate was decided by kings they had never seen. Philosophy turned to a new question: how can each person be happy, whatever happens around them.", [1]),
      P("Ο Διογένης ο Κυνικός, που πέθανε στην Κόρινθο το 323 π.Χ., ζούσε σε ένα πιθάρι και περιφρονούσε τα πλούτη και τις συμβάσεις. Όταν τον ρώτησαν από πού είναι, απάντησε, κατά τον Διογένη τον Λαέρτιο: «Κοσμοπολίτης», δηλαδή πολίτης του κόσμου. Η λέξη πέρασε σε όλες τις ευρωπαϊκές γλώσσες, ενώ η λέξη «κυνικός», από τον «κύνα», τον σκύλο, σήμερα σημαίνει κάποιον που δεν πιστεύει στις καλές προθέσεις των άλλων.",
        "Diogenes the Cynic, who died in Corinth in 323 BC, lived in a large storage jar and scorned wealth and conventions. When asked where he came from, he answered, according to Diogenes Laertius: 'A citizen of the world' (κοσμοπολίτης). The word passed into all European languages, while 'cynic', from κύων, 'dog' (his nickname), today means someone who does not believe in other people's good intentions.", [2]),
    ]),
    S("stoa", "Η Στοά", "The Stoa", [
      P("Γύρω στο 300 π.Χ. ο Ζήνων από το Κίτιο της Κύπρου άρχισε να διδάσκει στην Ποικίλη Στοά της αθηναϊκής αγοράς. Από τη στοά πήραν το όνομά τους οι μαθητές του, οι Στωικοί. Δίδασκαν ότι ο κόσμος κυβερνιέται από έναν λογικό νόμο, τον «λόγο», και ότι ο σοφός πρέπει να ζει «ομολογουμένως τη φύσει», σε αρμονία με τη φύση. Το μόνο αληθινό αγαθό είναι η αρετή· ο πλούτος, η υγεία, ακόμα και η ζωή, είναι «αδιάφορα».",
        "Around 300 BC Zeno of Citium in Cyprus began teaching in the Painted Stoa (Stoa Poikilē) on the Athenian agora. From the stoa his followers took their name, the Stoics. They taught that the world is governed by a rational law, the logos, and that the wise man must live 'in agreement with nature'. The only true good is virtue; wealth, health, even life itself, are 'indifferents' (ἀδιάφορα), some preferable to others but not truly good.", [3, 4]),
      P("Επειδή όλοι οι άνθρωποι μοιράζονται τον λόγο, οι Στωικοί θεωρούσαν ότι αποτελούν μια μεγάλη κοινότητα, πέρα από τα σύνορα και τις τάξεις. Η ιδέα αυτή επηρέασε αργότερα το ρωμαϊκό δίκαιο και τη χριστιανική σκέψη. Στα νέα ελληνικά, όπως και στα αγγλικά, «στωικός» λέγεται όποιος υπομένει τις δυσκολίες χωρίς παράπονα, και «στωικότητα» η στάση αυτή.",
        "Because all human beings share in reason, the Stoics held that they form one great community, beyond borders and social classes. This idea later influenced Roman law and Christian thought. In Modern Greek, as in English, someone who bears hardship without complaint is called στωικός, 'stoic', and the attitude στωικότητα.", [4, 5]),
    ]),
    S("garden", "Ο Κήπος του Επίκουρου", "The Garden of Epicurus", [
      P("Το 307/306 π.Χ. ο Επίκουρος αγόρασε στην Αθήνα έναν κήπο, όπου έζησε με τους φίλους και τους μαθητές του· ανάμεσά τους ήταν και γυναίκες και δούλοι, κάτι ασυνήθιστο για την εποχή. Δίδασκε ότι ο σκοπός της ζωής είναι η ηδονή, αλλά με αυτό εννοούσε την απουσία πόνου από το σώμα και ταραχής από την ψυχή, την «αταραξία», και όχι τις υπερβολές. Ένα λιτό γεύμα με ψωμί και νερό, γράφει, δίνει την ίδια ευχαρίστηση με ένα πολυτελές τραπέζι.",
        "In 307/306 BC Epicurus bought a garden in Athens, where he lived with his friends and pupils; among them were women and slaves, which was unusual for the time. He taught that the goal of life is pleasure, but by this he meant the absence of pain from the body and of disturbance from the soul, ataraxia, and not excess. A simple meal of bread and water, he writes in the Letter to Menoeceus, gives as much pleasure as a luxurious table.", [6, 7]),
      P("Για τον Επίκουρο ο κόσμος αποτελείται από άτομα και κενό· οι θεοί, αν υπάρχουν, δεν ασχολούνται με τους ανθρώπους, και ο θάνατος δεν πρέπει να μας φοβίζει, γιατί «όταν υπάρχουμε εμείς, ο θάνατος δεν υπάρχει, και όταν υπάρχει ο θάνατος, εμείς δεν υπάρχουμε». Οι αντίπαλοί του τον κατηγόρησαν ότι κήρυττε την καλοπέραση, και έτσι στα νέα ελληνικά «επικούρειος» σημαίνει συχνά απλώς «καλοφαγάς», κάτι που θα είχε μάλλον εκπλήξει τον ίδιο.",
        "For Epicurus the world consists of atoms and void; the gods, if they exist, do not concern themselves with humans, and death should not frighten us, because 'when we exist, death is not present, and when death is present, we do not exist'. His opponents accused him of preaching self-indulgence, and so in Modern Greek επικούρειος often simply means 'lover of good food', which would probably have surprised the man himself.", [7, 8]),
    ]),
  ],
  grammar=[
    G("B2", "Concessive relatives: ό,τι κι αν, όπου κι αν, όσο κι αν", "«Ό,τι κι αν συμβεί»",
      "Adding κι αν (και αν) to a relative gives 'no matter what/where/how much': ό,τι κι αν συμβαίνει 'whatever happens', όπου κι αν πας 'wherever you go', όσο κι αν προσπαθήσεις 'however hard you try'. The verb is in the indicative for facts, the subjunctive for possibilities.",
      [("Πώς μπορεί ο καθένας να είναι ευτυχισμένος, ό,τι κι αν συμβαίνει γύρω του;", "How can each person be happy, whatever happens around him?"),
       ("Όσο κι αν προσπαθείς, ο θάνατος δεν σε αφορά.", "However hard you try, death is no concern of yours.")]),
    G("B2", "Neuter nouns in -ος: το πάθος, του πάθους", "Ουδέτερα σε -ος",
      "A group of learned neuter nouns ends in -ος: το πάθος, το μέρος, το έθνος, το λάθος, το κράτος, το ήθος, το μέγεθος, το κέρδος. Genitive singular -ους (του πάθους), plural -η (τα πάθη), genitive plural -ών (των παθών). Do not confuse them with masculine -ος nouns like ο λόγος.",
      [("Ο σοφός δεν παρασύρεται από τα πάθη.", "The wise man is not carried away by the passions."),
       ("Η πόλη είχε χάσει μεγάλο μέρος της σημασίας της.", "The city had lost a large part of its importance.")]),
  ],
  terms=[
    T("ο κοσμοπολίτης", "cosmopolitan, citizen of the world", "Άνθρωπος που νιώθει σπίτι του σε όλο τον κόσμο.", "Someone who feels at home anywhere in the world."),
    T("κυνικός", "cynical; Cynic", "Που δεν πιστεύει στις καλές προθέσεις των άλλων· οπαδός του Διογένη.", "Distrustful of others' motives; a follower of Diogenes."),
    T("η στοά", "portico, colonnade; Stoa", "Σκεπαστός διάδρομος με κίονες· η σχολή του Ζήνωνα.", "A roofed walkway with columns; Zeno's school."),
    T("η αρετή", "virtue", "Η ηθική τελειότητα, η καλή διάθεση της ψυχής.", "Moral excellence."),
    T("στωικός", "stoic", "Που υπομένει τις δυσκολίες με ψυχραιμία· οπαδός της Στοάς.", "Enduring hardship calmly; a follower of the Stoa."),
    T("η ηδονή", "pleasure", "Το έντονο αίσθημα ευχαρίστησης.", "An intense feeling of enjoyment."),
    T("η αταραξία", "ataraxia, tranquillity", "Η ηρεμία της ψυχής, χωρίς φόβους και ανησυχίες.", "Peace of mind, free of fear and worry."),
    T("η καλοπέραση", "comfort, easy living", "Η άνετη και ευχάριστη ζωή.", "A comfortable, pleasant life."),
  ],
  questions=[
    Q("Ποιο ερώτημα απασχόλησε τη φιλοσοφία στην ελληνιστική εποχή;", ["Πώς μπορεί ο καθένας να είναι ευτυχισμένος", "Πώς να νικηθούν οι Πέρσες", "Πώς να χτιστούν ναοί", "Ποιο είναι το καλύτερο πολίτευμα για τη Σπάρτη"], 0, "Happiness whatever happens."),
    Q("Τι απάντησε ο Διογένης όταν τον ρώτησαν από πού είναι;", ["Κοσμοπολίτης", "Κορίνθιος", "Αθηναίος", "Σινωπεύς"], 0, "Diogenes Laertius 6.63."),
    Q("Από πού πήραν το όνομά τους οι Στωικοί;", ["Από την Ποικίλη Στοά όπου δίδασκε ο Ζήνων", "Από τον δάσκαλό τους, τον Στωικό", "Από μια πόλη της Κύπρου", "Από τη λέξη «στοιχείο»"], 0, "The Painted Stoa on the agora."),
    Q("Τι εννοούσε ο Επίκουρος με την «ηδονή»;", ["Την απουσία πόνου και ταραχής", "Τα πολυτελή γεύματα", "Τον πλούτο", "Τη δόξα"], 0, "Ataraxia and aponia."),
  ],
  vocab=["ορίζομαι", "πολίτης", "σημασία", "μοίρα", "στρέφομαι", "ερώτημα", "ευτυχισμένος", "περιφρονώ", "πλούτη", "σύμβαση", "πρόθεση", "διδάσκω", "κυβερνώ", "λογικός", "αρμονία", "μοιράζομαι", "υπομένω", "παράπονο", "ηδονή", "απουσία", "λιτός", "πολυτελής", "αντίπαλος", "κατηγορώ"],
  sources=[
    SRC("Long, A. A. (1986). Hellenistic Philosophy: Stoics, Epicureans, Sceptics. 2nd ed. London: Duckworth, ch. 1."),
    SRC("Diogenes Laertius, Lives of Eminent Philosophers 6.20–81 (Diogenes; 6.63 κοσμοπολίτης; 6.77 death at Corinth)."),
    SRC("Diogenes Laertius 7.1–5 (Zeno at the Stoa Poikile) and 7.87–89, 7.101–105 (life in agreement with nature; the indifferents)."),
    SRC("Long, A. A., & Sedley, D. N. (1987). The Hellenistic Philosophers. Vol. 1. Cambridge University Press, §§ 57, 58, 63, 67."),
    SRC("Λεξικό της κοινής νεοελληνικής (Ίδρυμα Τριανταφυλλίδη), λ. στωικός, επικούρειος, κυνικός.", "https://www.greek-language.gr/greekLang/modern_greek/tools/lexica/triantafyllides/"),
    SRC("Diogenes Laertius 10.10–11 (the Garden, its members and simple diet)."),
    SRC("Epicurus, Letter to Menoeceus 124–125 (death) and 130–132 (pleasure, simple food), in Diogenes Laertius 10.122–135."),
    SRC("Lucretius, On the Nature of Things 1.418–448 (atoms and void); Warren, J. (ed.) (2009). The Cambridge Companion to Epicureanism. Cambridge University Press."),
  ]))
